"""A2A server helpers shared by the Sanic integration."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import TYPE_CHECKING

from a2a.types import AgentCapabilities, AgentCard
from google.protobuf.json_format import ParseDict, ParseError

from rasa.core.a2a_server.agent_card_generator import (
    AgentCardGenerator,
    jsonrpc_supported_interfaces,
)
from rasa.core.a2a_server.config import A2AServerSettings
from rasa.core.a2a_server.engine_adapter import A2AEngineAdapter
from rasa.shared.exceptions import RasaException

if TYPE_CHECKING:
    from rasa.core.agent import Agent

# Required AgentCard JSON fields. Unrecognized fields are ignored so a newer
# card can still load; a file that omits these is not a card.
_REQUIRED_AGENT_CARD_FIELDS = (
    "name",
    "description",
    "version",
    "capabilities",
    "defaultInputModes",
    "defaultOutputModes",
    "skills",
)


def resolve_agent_card(
    config: A2AServerSettings,
    *,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
) -> AgentCard:
    """Load or build the ``AgentCard`` advertised by the A2A server.

    When ``agent_card_path`` is set, the static 1.0 JSON file is loaded.
    A top-level ``url`` is rejected. JSON-RPC interface URLs are set to
    ``config.effective_url(...)``. Repeated calls
    with the same arguments hit a bounded cache so the file is not re-read on
    every request.

    Otherwise a minimal placeholder card is returned (used before the agent
    model is loaded at startup). Placeholders are cheap to construct and are not
    cached to avoid accumulating entries for every distinct
    ``(port, interface, scheme)`` combination seen during the process lifetime.
    The runtime card, including CALM skills, is built later by
    :func:`resolve_a2a_agent_card_at_startup`.
    """
    if config.agent_card_path:
        return _load_static_agent_card_cached(
            config.agent_card_path,
            config.url,
            config.description,
            port,
            interface,
            scheme,
        )

    return _placeholder_agent_card(
        config,
        port=port,
        interface=interface,
        scheme=scheme,
    )


@lru_cache(maxsize=32)
def _load_static_agent_card_cached(
    agent_card_path: str,
    url: str | None,
    description: str,
    port: int | None,
    interface: str | None,
    scheme: str | None,
) -> AgentCard:
    """Read and validate a static AgentCard JSON file.

    Bounded to 32 entries: a typical deployment has a single file path with a
    fixed (port, interface, scheme), so the cache stays at one or two entries
    in production.  Tests call ``clear_agent_card_cache()`` between cases.
    """
    config = A2AServerSettings(
        url=url,
        agent_card_path=agent_card_path,
        description=description,
    )
    return _load_static_agent_card(
        config,
        port=port,
        interface=interface,
        scheme=scheme,
    )


async def resolve_a2a_agent_card_at_startup(
    agent: "Agent",
    config: A2AServerSettings,
    engine_adapter: A2AEngineAdapter,
    *,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
) -> AgentCard:
    """Resolve the runtime AgentCard once the agent model is loaded.

    Reached only when an ``a2a_server`` block is present. Startup always
    passes the adapter it built for that engine, and the adapter chooses the
    skills: CALM from flows, Mantle from the skill catalog. A static
    ``agent_card_path`` wins over the generated card for both engines and
    must be 1.0 JSON (``supportedInterfaces``, no top-level ``url``).
    """
    if config.agent_card_path:
        return _load_static_agent_card(
            config,
            port=port,
            interface=interface,
            scheme=scheme,
        )

    if agent.processor is None:
        raise RasaException(
            "Cannot generate A2A agent card: agent model is not loaded."
        )

    skills = await engine_adapter.get_card_skills()
    return AgentCardGenerator.card_from_skills(
        config,
        skills,
        port=port,
        interface=interface,
        scheme=scheme,
        assistant_name=_assistant_display_name(agent),
        version=_agent_card_version(agent),
    )


def _agent_card_version(agent: "Agent") -> str:
    """Derive the AgentCard ``version`` from the loaded model."""
    model_name = agent.model_name
    if model_name:
        if model_name.endswith(".tar.gz"):
            return model_name[: -len(".tar.gz")]
        return model_name

    if model_id := agent.model_id:
        return model_id

    return "1.0.0"


def _assistant_display_name(agent: "Agent") -> str:
    """Name advertised on a generated AgentCard.

    The id lives on the model metadata (``Agent.model_metadata.assistant_id``)
    for both engines: CALM training writes it from ``config.yml`` and Mantle
    packaging writes ``agent.id`` from ``agent.yml``. ``Domain`` has no
    ``config`` attribute, so the ``domain.config`` lookup below is a
    best-effort fallback that a loaded model never satisfies; do not drop the
    metadata lookup in its favour.
    """
    domain_config = getattr(agent.domain, "config", None) or {}
    if isinstance(domain_config, dict):
        assistant_id = domain_config.get("assistant_id")
        if isinstance(assistant_id, str) and assistant_id:
            return assistant_id

    metadata = getattr(agent, "model_metadata", None)
    metadata_id = getattr(metadata, "assistant_id", None)
    if isinstance(metadata_id, str) and metadata_id:
        return metadata_id
    return "Rasa Agent"


def agent_card_without_loaded_model(
    config: A2AServerSettings,
    *,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
) -> AgentCard:
    """Return the card to publish when no model is loaded.

    A static ``agent_card_path`` still wins. Otherwise the placeholder card
    advertises no skills.
    """
    if config.agent_card_path:
        return _load_static_agent_card(
            config,
            port=port,
            interface=interface,
            scheme=scheme,
        )
    return _placeholder_agent_card(
        config,
        port=port,
        interface=interface,
        scheme=scheme,
    )


def _placeholder_agent_card(
    config: A2AServerSettings,
    *,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
) -> AgentCard:
    return AgentCard(
        name="Rasa Agent",
        description=config.description,
        supported_interfaces=jsonrpc_supported_interfaces(
            config.effective_url(port=port, interface=interface, scheme=scheme)
        ),
        version="1.0.0",
        default_input_modes=["text", "text/plain"],
        default_output_modes=["text", "text/plain"],
        capabilities=AgentCapabilities(
            streaming=True,
            push_notifications=config.push_notifications_enabled,
        ),
        skills=[],
    )


def _load_static_agent_card(
    config: A2AServerSettings,
    *,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
) -> AgentCard:
    path = Path(config.agent_card_path)
    try:
        card_data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise RasaException(f"A2A agent card file not found: '{path}'") from exc
    except OSError as exc:
        raise RasaException(
            f"Could not read A2A agent card file '{path}': {exc}"
        ) from exc
    except json.JSONDecodeError as exc:
        raise RasaException(
            f"A2A agent card file '{path}' contains invalid JSON: {exc}"
        ) from exc

    if "url" in card_data:
        raise RasaException(
            f"A2A agent card file '{path}' has a top-level 'url'. "
            "Replace it with supportedInterfaces."
        )
    missing = [field for field in _REQUIRED_AGENT_CARD_FIELDS if field not in card_data]
    if missing:
        raise RasaException(
            f"A2A agent card file '{path}' does not match the AgentCard "
            f"schema (use supportedInterfaces): missing {', '.join(missing)}"
        )
    try:
        card = AgentCard()
        ParseDict(card_data, card, ignore_unknown_fields=True)
    except ParseError as exc:
        raise RasaException(
            f"A2A agent card file '{path}' does not match the AgentCard "
            f"schema (use supportedInterfaces): {exc}"
        ) from exc
    _apply_runtime_jsonrpc_url(
        card,
        config.effective_url(port=port, interface=interface, scheme=scheme),
    )
    return card


def _apply_runtime_jsonrpc_url(card: AgentCard, url: str) -> None:
    """Point JSON-RPC interfaces at the address this server is bound to."""
    updated = False
    for interface in card.supported_interfaces:
        if interface.protocol_binding == "JSONRPC":
            interface.url = url
            updated = True
    if not updated:
        card.supported_interfaces.extend(jsonrpc_supported_interfaces(url))
